// Code generated by gx api. DO NOT EDIT.

// GxError is one error of a failed call. A rule failure names the field.
export interface GxError {
  key: string
  field?: string
  message?: string
}

// GxAPIError is a call that the server did not run to its end.
export class GxAPIError extends Error {
  constructor(
    public status: number,
    public errors: GxError[],
  ) {
    super(errors[0]?.message ?? errors[0]?.key ?? 'the call failed with status ' + status)
  }
}

// ClientOptions sets the server of the calls and the headers of each call,
// for example the Authorization header.
export interface ClientOptions {
  baseURL?: string
  headers?: Record<string, string> | (() => Record<string, string> | Promise<Record<string, string>>)
  fetch?: typeof fetch
}

type Query = Record<string, unknown>

async function call<T>(options: ClientOptions, method: string, path: string, query: Query, body: Record<string, unknown> | undefined): Promise<T> {
  const params = new URLSearchParams()
  for (const [name, value] of Object.entries(query)) {
    if (value !== undefined) params.set(name, String(value))
  }
  const search = params.toString()
  const extra = typeof options.headers === 'function' ? await options.headers() : (options.headers ?? {})
  const headers: Record<string, string> = { Accept: 'application/json', ...extra }
  const init: RequestInit = { method, headers }
  if (body !== undefined) {
    headers['Content-Type'] = 'application/json'
    init.body = JSON.stringify(body)
  }
  const res = await (options.fetch ?? fetch)((options.baseURL ?? '') + path + (search === '' ? '' : '?' + search), init)
  if (res.status === 204) return undefined as T
  let data: unknown
  try {
    data = await res.json()
  } catch {
    data = undefined
  }
  if (!res.ok) throw new GxAPIError(res.status, (data as { errors?: GxError[] } | undefined)?.errors ?? [])
  return data as T
}

// Reads the totals of the basket.
export type BasketCountResult = {
  items: number
  lines: {
    qty: number
    sku: string
  }[]
}

// Sets the quantity of one line of the basket. A page gets the fragments that changed, and a JSON client gets the totals.
export type BasketSetQtyInput = {
  qty?: number
  sku: string
}

export type BasketSetQtyResult = {
  items: number
  lines: {
    qty: number
    sku: string
  }[]
}

// createClient returns one function for each action with .API().
export function createClient(options: ClientOptions = {}) {
  return {
    basketCount: (): Promise<BasketCountResult> =>
      call<BasketCountResult>(options, "GET", `/basket/count`, {}, undefined),
    basketSetQty: (input: BasketSetQtyInput): Promise<BasketSetQtyResult> =>
      call<BasketSetQtyResult>(options, "POST", `/basket/qty/${encodeURIComponent(String(input.sku))}`, {}, { "qty": input.qty }),
  }
}
